#!/usr/bin/env bash
#
# Generates the context and skills of each AI coding tool from this folder.
# .ai/AGENT.md and .ai/skills are the source: edit them, not the generated files.
#
# Usage: .ai/convert.sh [claude] [copilot] [codex] [opencode]
#        With no arguments, it generates all of them.

set -euo pipefail

readonly ALL_TARGETS="claude copilot codex opencode"
readonly MARKER_FILE=".generated-by-ai-convert"
readonly MARKER_LINE="<!-- Generated by .ai/convert.sh from .ai/AGENT.md. Do not edit: changes will be overwritten. -->"
readonly MAX_DESCRIPTION_LENGTH=1024

ai_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
root_dir="$(dirname "$ai_dir")"

context_file() {
    case "$1" in
        claude) echo "CLAUDE.md" ;;
        copilot) echo ".github/copilot-instructions.md" ;;
        codex | opencode) echo "AGENTS.md" ;;
    esac
}

skills_dir() {
    case "$1" in
        claude) echo ".claude/skills" ;;
        copilot) echo ".github/skills" ;;
        codex) echo ".agents/skills" ;;
        opencode) echo ".opencode/skills" ;;
    esac
}

usage() {
    sed -n '3,6p' "${BASH_SOURCE[0]}" | sed 's/^# \{0,1\}//'
}

fail() {
    echo "error: $1" >&2
    exit 1
}

frontmatter_value() {
    awk -v key="$2" '
        NR == 1 && $0 != "---" { exit }
        NR > 1 && $0 == "---" { exit }
        NR > 1 && index($0, key ":") == 1 { sub("^" key ":[ \t]*", ""); print; exit }
    ' "$1"
}

# All the tools share the SKILL.md format, but OpenCode and Codex reject skills without these fields,
# and OpenCode requires the name to match the folder.
validate_sources() {
    [ -f "$ai_dir/AGENT.md" ] || fail "missing .ai/AGENT.md"
    [ -d "$ai_dir/skills" ] || fail "missing .ai/skills"

    local skill name description
    for skill in "$ai_dir"/skills/*/; do
        [ -d "$skill" ] || continue
        name="$(basename "$skill")"
        [ -f "$skill/SKILL.md" ] || fail "skill '$name' has no SKILL.md"

        [ "$(frontmatter_value "$skill/SKILL.md" name)" = "$name" ] \
            || fail "skill '$name': the 'name' field must match the folder name"

        description="$(frontmatter_value "$skill/SKILL.md" description)"
        [ -n "$description" ] || fail "skill '$name' has no description"
        [ "${#description}" -le "$MAX_DESCRIPTION_LENGTH" ] \
            || fail "skill '$name': the description is longer than $MAX_DESCRIPTION_LENGTH characters"
    done
}

# Runs before writing anything, so a conflict can't leave a tool half generated.
check_conflicts() {
    local target context skills skill name
    for target in "$@"; do
        context="$root_dir/$(context_file "$target")"
        if [ -e "$context" ] && [ "$(head -n 1 "$context")" != "$MARKER_LINE" ]; then
            fail "$(context_file "$target") already exists and wasn't generated by this script. Move it first."
        fi

        skills="$root_dir/$(skills_dir "$target")"
        for skill in "$ai_dir"/skills/*/; do
            [ -d "$skill" ] || continue
            name="$(basename "$skill")"
            if [ -e "$skills/$name" ] && [ ! -e "$skills/$name/$MARKER_FILE" ]; then
                fail "$(skills_dir "$target")/$name already exists and wasn't generated by this script. Move it first."
            fi
        done
    done
}

write_context() {
    local destination="$root_dir/$(context_file "$1")"
    mkdir -p "$(dirname "$destination")"
    {
        echo "$MARKER_LINE"
        echo
        cat "$ai_dir/AGENT.md"
    } > "$destination"
}

# Only removes generated skills, so hand-written ones stay. This also drops the ones deleted from .ai/skills.
remove_generated_skills() {
    local skills="$1" skill
    [ -d "$skills" ] || return 0
    for skill in "$skills"/*/; do
        if [ -e "$skill/$MARKER_FILE" ]; then
            rm -rf "$skill"
        fi
    done
}

# The skills refer to the context by its name in .ai, which is different in each tool.
write_skills() {
    local skills="$root_dir/$(skills_dir "$1")" context skill destination file
    context="$(context_file "$1")"

    remove_generated_skills "$skills"
    for skill in "$ai_dir"/skills/*/; do
        [ -d "$skill" ] || continue
        destination="$skills/$(basename "$skill")"
        mkdir -p "$destination"
        cp -R "$skill". "$destination"
        : > "$destination/$MARKER_FILE"

        find "$destination" -type f -name '*.md' | while IFS= read -r file; do
            sed "s#AGENT\.md#$context#g" "$file" > "$file.tmp"
            mv "$file.tmp" "$file"
        done
    done
}

targets=()
for argument in "$@"; do
    case "$argument" in
        -h | --help) usage; exit 0 ;;
        claude | copilot | codex | opencode) targets+=("$argument") ;;
        *) usage >&2; fail "unknown target '$argument'" ;;
    esac
done

if [ "${#targets[@]}" -eq 0 ]; then
    read -r -a targets <<< "$ALL_TARGETS"
fi

validate_sources
check_conflicts "${targets[@]}"

for target in "${targets[@]}"; do
    write_context "$target"
    write_skills "$target"
    echo "$target: $(context_file "$target"), $(skills_dir "$target")"
done
